#include <stdio.h>
#include <stdint.h>
#include <string.h>

#define TABLE_SIZE (1u << 20)

static uint64_t substrings[TABLE_SIZE];
static uint64_t prefixes[TABLE_SIZE];
static uint64_t suffixes[TABLE_SIZE];

static uint64_t hash64(uint64_t x) {
    x += 0x9e3779b97f4a7c15ULL;
    x = (x ^ (x >> 30)) * 0xbf58476d1ce4e5b9ULL;
    x = (x ^ (x >> 27)) * 0x94d049bb133111ebULL;
    return x ^ (x >> 31);
}

static uint64_t make_key(uint64_t code, int length) {
    return code * 16 + (uint64_t)length;
}

static int contains(const uint64_t *table, uint64_t key) {
    size_t index = (size_t)hash64(key) & (TABLE_SIZE - 1);
    while (table[index] != 0) {
        if (table[index] == key) return 1;
        index = (index + 1) & (TABLE_SIZE - 1);
    }
    return 0;
}

static void insert(uint64_t *table, uint64_t key) {
    size_t index = (size_t)hash64(key) & (TABLE_SIZE - 1);
    while (table[index] != 0 && table[index] != key) {
        index = (index + 1) & (TABLE_SIZE - 1);
    }
    table[index] = key;
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    char s[32];

    for (int i = 0; i < n; i++) {
        if (scanf("%31s", s) != 1) return 0;
        int length = (int)strlen(s);
        int invalid = contains(substrings, make_key(0, 0));

        /* Check whether the whole string occurs inside an earlier string. */
        uint64_t code = 0;
        for (int j = 0; j < length; j++) {
            code = code * 26 + (uint64_t)(s[j] - 'a');
        }
        if (contains(substrings, make_key(code, length))) {
            invalid = 1;
        }

        /* Check substrings that cross the boundary between two earlier strings. */
        for (int split = 1; split < length && !invalid; split++) {
            uint64_t left = 0, right = 0;
            for (int j = 0; j < split; j++) {
                left = left * 26 + (uint64_t)(s[j] - 'a');
            }
            for (int j = split; j < length; j++) {
                right = right * 26 + (uint64_t)(s[j] - 'a');
            }

            if (contains(suffixes, make_key(left, split)) &&
                contains(prefixes, make_key(right, length - split))) {
                invalid = 1;
            }
        }

        if (invalid) {
            printf("%s\n", s);
            return 0;
        }

        /* Register all substrings, prefixes, and suffixes for later strings. */
        for (int start = 0; start < length; start++) {
            uint64_t subcode = 0;
            for (int end = start; end < length; end++) {
                subcode = subcode * 26 + (uint64_t)(s[end] - 'a');
                insert(substrings, make_key(subcode, end - start + 1));
            }
        }

        code = 0;
        for (int j = 0; j < length; j++) {
            code = code * 26 + (uint64_t)(s[j] - 'a');
            insert(prefixes, make_key(code, j + 1));
        }

        for (int start = 0; start < length; start++) {
            uint64_t suffix_code = 0;
            for (int j = start; j < length; j++) {
                suffix_code = suffix_code * 26 + (uint64_t)(s[j] - 'a');
            }
            insert(suffixes, make_key(suffix_code, length - start));
        }
    }

    printf("ok\n");
    return 0;
}
